1	package retention
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 保存的档案集合中同一编号出现两次时，即使 JSON 本身能解析，Open 也必须
10	// 按保存记录损坏失败（ErrCorruptState）：错误指出重复的档案编号并说明
11	// 登记重复，原文件保持原样。普通解码会让后一份登记静默覆盖前一份（例如
12	// 前一份带未解除诉讼冻结、后一份冻结列表为空，只剩后者会被误判为可以
13	// 销毁），绝不能接受这种覆盖。两份内容不同、或类别/日期/冻结/修订历史
14	// 完全相同，都不是合并或忽略重复的理由。
15	func TestOpenRejectsDuplicateArchiveRegistration(t *testing.T) {
16		activeFreeze := `{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":false}`
17		// rec 构造一份登记记录；key 给出它在档案集合对象中的键（可含转义）。
18		rec := func(id, category, end, freezes string) string {
19			return `{"id":"` + id + `","category":"` + category + `","start":"2020-01-01","end":"` + end +
20				`","initial_end":"` + end + `","destroyed":false,"freezes":[` + freezes + `]}`
21		}
22		entry := func(key, recordJSON string) string { return `"` + key + `":` + recordJSON }
23		state := func(entries string) string {
24			return `{"version":1,"archives":{` + entries + `},"manifests":{}}`
25		}
26		a1Frozen := rec("A-1", "合同", "2025-01-10", activeFreeze)
27		a1NoFreeze := rec("A-1", "合同", "2025-01-10", "")
28	
29		corrupt := map[string]struct {
30			state   string
31			wantID  string
32			wantAll []string
33		}{
34			"前一份带未解除冻结后一份冻结为空": {
35				state(entry("A-1", a1Frozen) + "," + entry("A-1", a1NoFreeze)),
36				"A-1", []string{"A-1"},
37			},
38			"顺序相反同样拒绝不得按冻结挑选": {
39				state(entry("A-1", a1NoFreeze) + "," + entry("A-1", a1Frozen)),
40				"A-1", []string{"A-1"},
41			},
42			"两份登记内容完全一致": {
43				state(entry("A-1", a1Frozen) + "," + entry("A-1", a1Frozen)),
44				"A-1", []string{"A-1"},
45			},
46			"两份内容不同类别不同": {
47				state(entry("A-1", a1NoFreeze) + "," +
48					entry("A-1", rec("A-1", "凭证", "2026-12-31", ""))),
49				"A-1", []string{"A-1"},
50			},
51			"后一份期限更长也不得挑选可信记录": {
52				state(entry("A-1", a1Frozen) + "," +
53					entry("A-1", rec("A-1", "合同", "2099-01-01", ""))),
54				"A-1", []string{"A-1"},
55			},
56			"Unicode转义键与直接键同编号": {
57				// Go 源里的 \\u0031 是字面的反斜杠+u0031，JSON 解码后才是字符 1，
58				// 与直接写出的 A-1 是同一个编号。
59				`{"version":1,"archives":{"A-1":` + a1Frozen +
60					`,"A-\u0031":` + a1NoFreeze + `},"manifests":{}}`,
61				"A-1", []string{"A-1"},
62			},
63			"多份档案中第二份编号重复": {
64				state(entry("A-1", a1NoFreeze) + "," + entry("B-7", rec("B-7", "凭证", "2025-06-30", "")) +
65					"," + entry("B-7", rec("B-7", "凭证", "2025-06-30", ""))),
66				"B-7", []string{"B-7"},
67			},
68		}
69		for name, tc := range corrupt {
70			t.Run(name, func(t *testing.T) {
71				dir := t.TempDir()
72				writeStateFile(t, dir, tc.state)
73	
74				s, err := Open(dir)
75				if err == nil {
76					s.Close()
77					t.Fatal("同一档案编号登记两次时不应打开成功")
78				}
79				if !errors.Is(err, ErrCorruptState) {
80					t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
81				}
82				msg := err.Error()
83				for _, want := range tc.wantAll {
84					if !strings.Contains(msg, want) {
85						t.Fatalf("错误信息应指出重复编号 %q，得到 %v", want, err)
86					}
87				}
88				if !strings.Contains(msg, "重复") || !strings.Contains(msg, "登记") {
89					t.Fatalf("错误信息应说明登记重复，得到 %v", err)
90				}
91				if got := readStateFile(t, dir); got != tc.state {
92					t.Fatalf("打开失败后原文件被改动:\n%q", got)
93				}
94			})
95		}
96	
97		// 对照组：不同编号各自登记一次不受影响——即使每条登记内容里都出现相同的
98		// 字段名（id、freezes 内的 id），那也只是登记记录的内部字段，不是档案
99		// 集合的重复键；旧档案缺少 initial_end 与 archives 为 null 继续合法。
100		t.Run("合法记录对照组", func(t *testing.T) {
101			valid := map[string]string{
102				"不同编号各登记一次且内部字段同名": state(
103					entry("A-1", rec("A-1", "合同", "2025-01-10", activeFreeze)) + "," +
104						entry("A-2", rec("A-2", "合同", "2025-01-10", activeFreeze))),
105				"转义键解码后仍是另一个编号": `{"version":1,"archives":{"A-1":` + a1NoFreeze +
106					`,"A-\u0032":` + rec("A-2", "凭证", "2025-06-30", "") + `},"manifests":{}}`,
107				"archives为null按空库": `{"version":1,"archives":null,"manifests":{}}`,
108				"旧档案缺少initial_end": `{"version":1,"archives":{"A-1":` +
109					`{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","destroyed":false,"freezes":[]}` +
110					`},"manifests":{}}`,
111			}
112			for name, content := range valid {
113				t.Run(name, func(t *testing.T) {
114					dir := t.TempDir()
115					writeStateFile(t, dir, content)
116					s, err := Open(dir)
117					if err != nil {
118						t.Fatalf("合法记录应能打开: %v", err)
119					}
120					defer s.Close()
121				})
122			}
123		})
124	}
125	
126	// 保管库打开后保存内容才出现同编号重复登记：下一次使用有效输入查询历史、
127	// 取回清册（含已成功申请的幂等重放）、销毁前核对与各项办理都必须按整库
128	// 记录损坏失败——即使操作的是另一份正常档案——不返回正常历史、清册或部分
129	// 核对报告，不写入新记录、不改变销毁状态或生成清册，原保存内容保持原样。
130	func TestDuplicateArchiveRegistrationAfterOpenFailsAllOperations(t *testing.T) {
131		dir := t.TempDir()
132		s, err := Open(dir)
133		if err != nil {
134			t.Fatal(err)
135		}
136		defer s.Close()
137		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
138		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-06-30")
139		reg(t, s, "A-3", "单据", "2020-01-01", "2025-01-10")
140		if err := s.Freeze(FreezeInput{
141			ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05"),
142		}); err != nil {
143			t.Fatal(err)
144		}
145		// A-3 先合法销毁，供损坏后验证“取回清册”同样整库失败。
146		if _, err := s.Destroy(DestructionRequest{
147			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
148		}); err != nil {
149			t.Fatal(err)
150		}
151		if _, found, err := s.GetManifest("APP-3"); err != nil || !found {
152			t.Fatalf("损坏前清册应可取回: found=%v err=%v", found, err)
153		}
154	
155		// 在档案集合末尾再写入一份 A-1：期限相同但冻结列表为空——正是“先保存
156		// 带未解除冻结的 A-1，随后又保存一份无冻结 A-1”的情形。普通解码会只剩
157		// 后一份，核对将误报可以办理。
158		good := readStateFile(t, dir)
159		dup := `,
160	    "A-1": {"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","destroyed":false,"freezes":[]}`
161		corrupt := strings.Replace(good, "\n  },\n  \"manifests\"", dup+"\n  },\n  \"manifests\"", 1)
162		if corrupt == good {
163			t.Fatal("未找到档案集合的结束位置，测试夹具失效")
164		}
165		writeStateFile(t, dir, corrupt)
166		corruptContent := readStateFile(t, dir)
167	
168		// 重新打开必须失败，错误指出重复编号 A-1 并说明登记重复。
169		s2, err := Open(dir)
170		if err == nil {
171			s2.Close()
172			t.Fatal("档案集合出现同编号登记时，打开必须失败")
173		}
174		if !errors.Is(err, ErrCorruptState) ||
175			!strings.Contains(err.Error(), "A-1") ||
176			!strings.Contains(err.Error(), "重复") {
177			t.Fatalf("打开错误应为 ErrCorruptState 并指出重复的 A-1，得到 %v", err)
178		}
179	
180		// 已打开实例：即使本次只操作与重复登记无关的正常档案 A-2，
181		// 也必须按整库损坏失败。
182		if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
183			t.Fatalf("损坏后查询无关档案也必须失败且无结论: found=%v err=%v", found, err)
184		}
185		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
186			t.Fatalf("损坏后 History 必须失败且不得给出登记/冻结历史: found=%v err=%v", found, err)
187		}
188		if m, found, err := s.GetManifest("APP-3"); !errors.Is(err, ErrCorruptState) || found || m.ApplicationID != "" {
189			t.Fatalf("损坏后 GetManifest 必须失败: found=%v err=%v %+v", found, err, m)
190		}
191		if r, err := s.Check(CheckRequest{
192			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
193		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
194			t.Fatalf("损坏后 Check 必须失败且不得给出可以办理等结论或部分报告: %+v err=%v", r, err)
195		}
196		// 关键回归点：损坏状态下绝不能把“冻结列表为空的后一份 A-1”当作依据，
197		// 在截止日当天给出可以办理甚至完成销毁。
198		if r, err := s.Check(CheckRequest{
199			ApplicationID: "APP-8", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
200		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
201			t.Fatalf("损坏后对 A-1 的核对也必须失败，不能误报可以办理: %+v err=%v", r, err)
202		}
203		if m, err := s.Destroy(DestructionRequest{
204			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
205		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
206			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
207		}
208		if m, err := s.Destroy(DestructionRequest{
209			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
210		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
211			t.Fatalf("损坏后不得凭后一份无冻结登记销毁 A-1: %+v err=%v", m, err)
212		}
213		// 已成功申请的幂等重放同样不能取回原清册。
214		if m, err := s.Destroy(DestructionRequest{
215			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
216		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
217			t.Fatalf("损坏后已成功申请的重放也必须失败且不得返回原清册: %+v err=%v", m, err)
218		}
219		if err := s.Register(RegisterInput{
220			ID: "A-4", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-06-30"),
221		}); !errors.Is(err, ErrCorruptState) {
222			t.Fatalf("损坏后 Register 必须失败: %v", err)
223		}
224		if err := s.Freeze(FreezeInput{
225			ArchiveID: "A-2", FreezeID: "F-X", Reason: "诉讼", FrozenOn: MustParseDate("2025-06-01"),
226		}); !errors.Is(err, ErrCorruptState) {
227			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
228		}
229		if err := s.Release(ReleaseInput{
230			ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-08"),
231		}); !errors.Is(err, ErrCorruptState) {
232			t.Fatalf("损坏后 Release 必须失败: %v", err)
233		}
234		if _, err := s.Revise(ReviseInput{
235			RevisionID: "R-9", ArchiveID: "A-2",
236			OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
237			RevisedOn: MustParseDate("2025-06-01"), Reason: "延期",
238		}); !errors.Is(err, ErrCorruptState) {
239			t.Fatalf("损坏后 Revise 必须失败: %v", err)
240		}
241	
242		// 失败不得触发修复：不删除重复登记、不挑选其中一份，原保存内容保持原样。
243		if got := readStateFile(t, dir); got != corruptContent {
244			t.Fatalf("失败后原保存内容被改动:\n%q", got)
245		}
246	
247		// 去掉重复登记后，合法记录恢复可用：A-1 的冻结历史仍是损坏前那一条
248		// 未解除冻结，不会被“无冻结的第二份”顶替；无关档案业务不受影响。
249		writeStateFile(t, dir, good)
250		h, found, err := s.History("A-1")
251		if err != nil || !found {
252			t.Fatalf("恢复后查询应成功: found=%v err=%v", found, err)
253		}
254		if len(h.Freezes) != 1 || h.Freezes[0].ID != "F-1" || h.Freezes[0].Released {
255			t.Fatalf("恢复后 A-1 应仍保留唯一一条未解除冻结 F-1: %+v", h.Freezes)
256		}
257		if r, err := s.Check(CheckRequest{
258			ApplicationID: "APP-8", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
259		}); err != nil || r.Status != CheckBlocked {
260			t.Fatalf("恢复后未解除冻结仍应阻止销毁 A-1: %+v err=%v", r, err)
261		}
262		if _, err := s.Destroy(DestructionRequest{
263			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
264		}); err != nil {
265			t.Fatalf("恢复后无关档案应能正常办理销毁: %v", err)
266		}
267	}
