17			return "", nil, nil, err
18		}
19		if len(rawIDs) == 0 {
20			return "", nil, nil, fmt.Errorf("retention: 申请 %s 的销毁名单为空: %w",
21				appID, ErrEmptyDestructionList)
22		}
23	
24		// 规范化名单并检查名单内重复（输入校验先于任何业务判断）。
25		// 同一编号仅因首尾空白不同也视为重复。
26		ids := make([]string, 0, len(rawIDs))
27		for _, raw := range rawIDs {
28			id, err := requireText(raw, "档案编号")
29			if err != nil {
30				return "", nil, nil, err
31			}
32			ids = append(ids, id)
33		}
34		seen := make(map[string]struct{}, len(ids))
35		for _, id := range ids {
36			if _, dup := seen[id]; dup {
37				return "", nil, nil, fmt.Errorf("retention: 申请 %s 的销毁名单中档案 %s 重复: %w",
38					appID, id, ErrDuplicateSelection)
39			}
40			seen[id] = struct{}{}
41		}
42		return appID, ids, seen, nil
43	}
44	
45	// evaluateArchive 按当前保存状态核对一份档案在给定处理日期下的全部销毁阻碍，
46	// 是只读核对（Check）与正式销毁（Destroy）共用的同一份业务规则：
47	// 到期以当前生效的保管截止日（含修订后的日期）为准，处理日期不早于截止日即到期；
48	// 任一未解除冻结都是阻碍，已解除记录只保留在历史中。
49	//
50	// 阻碍按固定顺序列出：不存在、已销毁、未到期，然后是每条未解除冻结各一条
51	// （沿用冻结登记顺序）。已销毁的档案只带已销毁阻碍，并附所属清册的申请编号
52	// 和处理日期；不存在的编号只带不存在阻碍。返回结果同时携带登记内容，
53	// 供核对报告展示，也供正式销毁在失败时定位档案。
54	func evaluateArchive(data *storeData, id string, processedOn Date) ArchiveCheckResult {
55		r := ArchiveCheckResult{ID: id, Obstructions: []CheckObstruction{}}
56		ar, ok := data.Archives[id]
57		if !ok {
58			r.Obstructions = append(r.Obstructions, CheckObstruction{Kind: ObstructionMissing})
59			return r
60		}
61		r.Exists = true
62		r.Category = ar.Category
63		r.Start = ar.Start
64		r.End = ar.End
65		r.Destroyed = ar.Destroyed
66	
67		if ar.Destroyed {
68			// 已销毁档案给出所属清册的申请编号和处理日期。
69			obs := CheckObstruction{Kind: ObstructionDestroyed}
70			if rec, ok := data.Manifests[ar.ManifestID]; ok {
71				obs.ManifestApplicationID = rec.ApplicationID
72				// 通过校验的已关闭清册必然带有有效处理日期。
73				if rec.ProcessedOn != nil {
74					obs.ProcessedOn = *rec.ProcessedOn
75				}
76			} else {
77				obs.ManifestApplicationID = ar.ManifestID
78			}
79			r.Obstructions = append(r.Obstructions, obs)
80			return r
81		}
82	
83		// 未到期与未解除冻结可能同时成立，两类问题都要列出。
84		if processedOn.Before(ar.End) {
85			r.Obstructions = append(r.Obstructions, CheckObstruction{Kind: ObstructionNotExpired})
86		}
87		// 每条未解除冻结各成一条阻碍，顺序沿用冻结历史（登记顺序）。
88		for _, f := range ar.Freezes {
89			if f.Released {
90				continue
91			}
92			r.Obstructions = append(r.Obstructions, CheckObstruction{
93				Kind: ObstructionActiveFreeze,
94				Freeze: ActiveFreezeInfo{
95					FreezeID: f.ID,
96					Reason:   f.Reason,
97					FrozenOn: f.FrozenOn,
98				},
99			})
100		}
101		return r
102	}
103	
104	// firstObstructionError 把共用核对结果中的第一条阻碍转换为正式销毁的失败错误。
105	// 阻碍顺序固定（不存在、已销毁、未到期、未解除冻结），因此同一档案同时存在
106	// 多个问题时，错误类别与定位信息与既有判断先后一致。
107	func firstObstructionError(r ArchiveCheckResult, processedOn Date) error {
108		switch obs := r.Obstructions[0]; obs.Kind {
109		case ObstructionMissing:
110			return fmt.Errorf("retention: 档案 %s 不存在: %w", r.ID, ErrNotFound)
111		case ObstructionDestroyed:
112			return fmt.Errorf("retention: 档案 %s 已在清册 %s 中，不能再次销毁: %w",
113				r.ID, obs.ManifestApplicationID, ErrArchiveAlreadyOnManifest)
114		case ObstructionNotExpired:
115			return fmt.Errorf("retention: 档案 %s 尚未到期（截止日 %s，处理日期 %s）: %w",
116				r.ID, r.End, processedOn, ErrNotExpired)
117		case ObstructionActiveFreeze:
118			return fmt.Errorf("retention: 档案 %s 有未解除的冻结 %s: %w",
119				r.ID, obs.Freeze.FreezeID, ErrActiveFreeze)
120		}
121		return nil
122	}
123	
124	// Check 在正式办理销毁前做一次只读核对。
125	//
126	// 调用者提交申请编号、处理日期和档案编号名单，得到整批申请能否办理的报告，
127	// 一次看清所有阻碍。核对不销毁档案、不生成或改写清册，也不占用申请编号；
128	// 核对后（无论报告结论如何，甚至读取本地记录失败）仍可沿用同一编号继续
129	// 核对或正式提交。
130	//
131	// 报告区分四种结论：
132	//   - CheckReady 可以办理：申请编号尚未成功使用，名单中每份档案均无阻碍；
133	//   - CheckBlocked 存在阻碍：申请编号尚未成功使用，至少一份档案存在阻碍，
134	//     Results 按提交顺序列出每份档案的核对结果和全部适用阻碍；
135	//   - CheckReplayable 可以取回原清册：申请编号已成功使用，且日期与档案集合
136	//     （顺序无关）与原申请相同，Manifest 返回原清册，不因档案已销毁而判受阻；
137	//   - CheckConflict 申请编号冲突：沿用该编号但改变了日期或集合，Manifest 附原清册。
138	//
139	// 申请编号已被本保管库内任意一条成功的期限修订占用时（与本次选中的档案无关，
140	// 该档案后来再次修订或已销毁都不释放编号），整次核对明确失败，返回
141	// ErrRevisionConflict，报告为空——不列出逐份档案结果，也不附清册。
142	// 只有成功修订才占用编号；失败过的修订提交不影响核对。
143	//
144	// 到期与冻结判断与 Destroy 共用同一份实现（evaluateArchive）：处理日期达到
145	// 截止日当天即到期，任一未解除冻结都会阻止销毁，已解除记录不作为阻碍。
146	//
147	// 申请编号或任一档案编号为空白、日期缺失或不是真实的 YYYY-MM-DD、
148	// 名单为空或含重复编号时，整次核对明确失败，不返回部分报告；
149	// 读取本地记录失败同样明确失败，绝不会用旧报告充当本次结果。
150	//
151	// 报告中的档案结果与清册来自同一次已保存状态读取；报告只说明核对当时的
152	// 情况，之后状态若变化，正式提交仍按最新状态判断。返回值是复制生成的
153	// 只读视图，调用者修改报告或其中清册不影响已保存的历史。
154	func (s *Store) Check(req CheckRequest) (CheckReport, error) {
155		appID, ids, seen, err := validateBatchInputs(req.ApplicationID, req.ProcessedOn, req.ArchiveIDs)
156		if err != nil {
157			return CheckReport{}, err
158		}
159	
160		var report CheckReport
161		err = s.view(func(data *storeData) error {
162			report = CheckReport{
163				ApplicationID: appID,
164				ProcessedOn:   req.ProcessedOn,
165				Results:       make([]ArchiveCheckResult, 0, len(ids)),
166			}
167	
168			// 申请编号已成功使用：只判断能否取回原清册或编号冲突，两者都附原清册。
169			// 原清册取自当前这一次状态读取，与下面逐份核对看到的记录同源。
170			if existing, ok := data.Manifests[appID]; ok {
171				m := manifestFromRecord(existing)
172				report.Manifest = &m
173				if sameApplication(existing, req.ProcessedOn, seen) {
174					report.Status = CheckReplayable
175				} else {
176					report.Status = CheckConflict
177				}
178				return nil
179			}
180	
181			// 申请编号已被任意一条成功的期限修订占用：整次核对失败，报告为空。
182			// 编号占用属于整个保管库，与本次选中的档案无关；失败过的修订不占用编号。
183			if _, rec := findRevision(data, appID); rec != nil {
184				return fmt.Errorf("retention: 申请编号 %s 已用于期限修订: %w",
185					appID, ErrRevisionConflict)
186			}
187	
188			// 申请编号尚未成功使用：按提交顺序逐份核对，每份列出全部适用阻碍。
189			// 核对规则与正式销毁共用 evaluateArchive，两处结论必然一致。
190			anyBlocked := false
191			for _, id := range ids {
192				r := evaluateArchive(data, id, req.ProcessedOn)
193				if len(r.Obstructions) > 0 {
194					anyBlocked = true
195				}
196				report.Results = append(report.Results, r)
197			}
198	
199			if anyBlocked {
200				report.Status = CheckBlocked
201			} else {
202				report.Status = CheckReady
203			}
204			return nil
205		})
206		if err != nil {
207			return CheckReport{}, err
208		}
209		return report, nil
210	}
